/* nemotron_chat_gate -- the Nemotron-H tokenizer, renderer, span map and output parser graded against HF and vLLM
 * (L296 N8).  Model-free; seconds.
 *
 * Goldens: tests/test-vectors/nemotron_h/, generated by tests/nemotron/gen_nemotron_goldens.py from tokenizers'
 * Tokenizer, transformers' apply_chat_template (the checkpoint's chat_template.jinja) and vLLM's parser engine in its
 * nemotron_v3 configuration (meta.json records the versions and the input hashes).
 *
 *   T1 adversarial strings        encode(text) == HF ids
 *   T2 span guard                 encode(text, client spans) == tokenizers' components with added tokens cut only
 *                                 outside the spans
 *   T3 every scalar value         per-4096-codepoint chunk: count + sha1(ids) == HF
 *   T4 calibration corpus         HF-rendered rows: count + sha1(ids) == HF   (--calib)
 *   R1 render hand cases          text == HF; the message-level spans == HF's (the tools block's are the renderer's
 *                                 own); ids == HF (or the guarded ids where client text spells a marker); refusals
 *   R2 render corpus              every L216 case, two configurations: sha1(text), sha1(ids) where derivable, refusal
 *                                 keys == HF, per case file   (--cases)
 *   P1 output parser round trip   every assistant turn of the corpus with reasoning rendered, its sampled bytes parsed
 *                                 back, re-rendered: byte-identical; any chunking gives the same events   (--cases)
 *   P2 parser vs vLLM             the hand units and every corpus turn read by vLLM's nemotron_v3 engine: reasoning
 *                                 and call names equal; content equal up to the one departure (vLLM strips a turn's
 *                                 content when it holds calls); arguments equal as JSON or in a named departure class
 *   E1 effort map                 the template's three levels and their spellings
 *   C1 turn-by-turn composition   head + turns + sampled turns + closes == the full render (no history truncation in
 *                                 a tool loop), text and ids
 *
 * usage: nemotron_chat_gate --tok DIR --vectors DIR [--cases DIR] [--calib FILE]
 *        DIR = the checkpoint's tokenizer.json + generation_config.json */
#include <math.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <algorithm>
#include <map>
#include <string>
#include <vector>

#include "bpe_gate_util.h"
#include "../src/lib/nemotron_chat.h"

/* T3's context for one codepoint c (gen_nemotron_goldens.py sweep_text) */
static std::string sweep_context(const std::string &c) { return "x" + c + c + c + " " + c + "1'" + c + "Ab" + c + "\n"; }

/* ---- the API conversation -> renderer input ---------------------------------------------------------------- */

struct conv {
    std::vector<nemotron_msg_in> msgs;
    std::vector<std::vector<nemotron_tool_call_in>> calls;
    std::vector<std::string> store;   /* owned strings; reserved up front so c_str() stays put */
    std::string tools;
    bool has_tools = false;
    bool parts = false;               /* a content-parts message: v1's renderer takes text only */
};

static const char *keep(conv *c, const std::string &s) {
    c->store.push_back(s);
    return c->store.back().c_str();
}

static void build_conv(const pyjson_value &messages, const pyjson_value *tools, conv *c) {
    size_t strings = 1;
    for (const auto &m : messages.a) {
        strings += 4;
        if (const pyjson_value *tc = m.get("tool_calls")) strings += 2 * tc->a.size();
    }
    c->store.reserve(strings);
    c->msgs.resize(messages.a.size());
    c->calls.resize(messages.a.size());
    for (size_t i = 0; i < messages.a.size(); i++) {
        const pyjson_value &m = messages.a[i];
        nemotron_msg_in &q = c->msgs[i];
        q = {};
        const pyjson_value *role = m.get("role");
        q.role = keep(c, role ? role->s : "");
        const pyjson_value *content = m.get("content");
        q.content = content && content->kind == pyjson_value::STR ? keep(c, content->s) : NULL;
        c->parts |= content && content->kind == pyjson_value::ARR;
        const pyjson_value *reasoning = m.get("reasoning_content");
        q.reasoning = reasoning && reasoning->kind == pyjson_value::STR ? keep(c, reasoning->s) : NULL;
        if (const pyjson_value *tcs = m.get("tool_calls")) {
            for (const auto &tc : tcs->a) {
                const pyjson_value *fn = tc.get("function");
                if (!fn) fn = &tc;
                const pyjson_value *name = fn->get("name");
                const pyjson_value *args = fn->get("arguments");
                std::string a;
                if (args && args->kind == pyjson_value::STR) a = args->s;
                else if (args && args->kind != pyjson_value::NUL) pyjson_dump(*args, &a);
                c->calls[i].push_back({keep(c, name && name->kind == pyjson_value::STR ? name->s : ""), keep(c, a)});
            }
            q.calls = c->calls[i].data();
            q.n_calls = (int)c->calls[i].size();
        }
    }
    if (tools && tools->kind != pyjson_value::NUL) {
        c->has_tools = !(tools->kind == pyjson_value::ARR && tools->a.empty());
        if (tools->kind == pyjson_value::STR) {
            c->tools = tools->s;
            c->has_tools = c->tools != "[]";
        } else {
            pyjson_dump(*tools, &c->tools);
        }
    }
}

static nemotron_effort effort_of(const std::string &name) {
    if (name == "default") return nemotron_effort_default();
    nemotron_effort e;
    if (!nemotron_effort_parse(name.c_str(), &e)) {
        fprintf(stderr, "nemotron_chat_gate: bad effort %s\n", name.c_str());
        exit(2);
    }
    return e;
}

static bool render(const conv &c, nemotron_effort effort, bool gen, nemotron_render_out *out, std::string *refusal) {
    if (c.parts) {
        *refusal = "content_parts";
        return false;
    }
    nemotron_render_in in;
    in.msgs = c.msgs.data();
    in.n_msgs = (int)c.msgs.size();
    in.tools_json = c.has_tools ? c.tools.c_str() : NULL;
    in.effort = effort;
    in.add_generation_prompt = gen;
    char err[400];
    if (nemotron_chat_render(in, out, err, sizeof err)) return true;
    const char *colon = strchr(err, ':');
    refusal->assign(err, colon ? (size_t)(colon - err) : strlen(err));
    return false;
}

static std::string spans_text(const std::vector<pulsar_text_span> &spans) {
    std::string s;
    char b[32];
    for (size_t i = 0; i < spans.size(); i++) {
        snprintf(b, sizeof b, "%s%u-%u", i ? "," : "", spans[i].lo, spans[i].hi);
        s += b;
    }
    return s;
}

/* the spans outside the tools block (the block's own spans are the renderer's; the generator derives the others) */
static std::vector<pulsar_text_span> message_spans(const std::string &text, const std::vector<pulsar_text_span> &spans) {
    const size_t lo = text.find("# Tools\n\nYou have access"), hi = text.find("</IMPORTANT>");
    std::vector<pulsar_text_span> out;
    for (const auto &s : spans)
        if (lo == std::string::npos || hi == std::string::npos || s.hi <= lo || s.lo >= hi) out.push_back(s);
    return out;
}

/* ---- sections ---------------------------------------------------------------------------------------------- */

static void r1_hand(const bpe_tokenizer *t, const std::string &dir) {
    const pyjson_value v = load_json(dir + "/render_cases.json");
    int bad = 0, refusals = 0, guarded = 0, no_spans = 0;
    for (const auto &c : v.a) {
        const std::string &name = c.get("name")->s;
        conv cv;
        build_conv(*c.get("messages"), c.get("tools"), &cv);
        nemotron_render_out out;
        std::string refusal;
        const bool ok = render(cv, effort_of(c.get("effort")->s), c.get("gen")->b, &out, &refusal);
        const pyjson_value *ex = c.get("expect");
        const int before = g_fail;
        g_checks++;
        if (const pyjson_value *want_refusal = ex->get("refusal")) {
            refusals++;
            if (ok || refusal != want_refusal->s)
                fail("R1 %s: expected refusal %s, got %s", name.c_str(), want_refusal->s.c_str(),
                     ok ? "a render" : refusal.c_str());
        } else if (!ok) {
            fail("R1 %s: refused (%s)", name.c_str(), refusal.c_str());
        } else {
            const std::string &want = ex->get("text")->s;
            if (out.text != want) {
                size_t i = 0;
                while (i < out.text.size() && i < want.size() && out.text[i] == want[i]) i++;
                std::string ours, theirs;
                pyjson_dump_string(out.text.data() + i, std::min<size_t>(80, out.text.size() - i), &ours);
                pyjson_dump_string(want.data() + i, std::min<size_t>(80, want.size() - i), &theirs);
                fail("R1 %s: text differs at byte %zu: ours %s vs HF %s", name.c_str(), i, ours.c_str(), theirs.c_str());
            }
            const pyjson_value *sp = ex->get("spans");
            if (sp && sp->kind == pyjson_value::ARR) {
                const std::string ours = spans_text(message_spans(out.text, out.spans));
                const std::string theirs = spans_text(json_spans(*sp));
                if (ours != theirs) fail("R1 %s: spans %s vs HF %s", name.c_str(), ours.c_str(), theirs.c_str());
            } else {
                no_spans++;
            }
            const pyjson_value *ids = ex->get("ids");
            if (ids && ids->kind == pyjson_value::ARR) {
                const std::vector<int> got = encode(t, out.text, &out.spans), want_ids = json_ids(*ids);
                if (got != want_ids) fail("R1 %s: ids %s", name.c_str(), first_diff(got, want_ids).c_str());
                guarded += ex->get("ids_kind")->s == "guarded";
            }
        }
        bad += g_fail != before;
    }
    printf("R1 render hand cases: %zu (%d refusals, %d graded on the guarded ids, %d without derivable spans), "
           "%d mismatched\n", v.a.size(), refusals, guarded, no_spans, bad);
}

static void r2_corpus(const bpe_tokenizer *t, const std::string &dir, const std::string &cases_dir) {
    std::string tsv;
    if (!read_file(dir + "/render_corpus.tsv", &tsv)) { fail("R2: no render_corpus.tsv"); return; }
    static const char *efforts[] = {"none", "medium", "default"};
    int lines = 0, bad = 0, cases_total = 0, rendered_total = 0, compared_total = 0;
    long tokens_total = 0;
    std::map<std::string, int> refusals_total;
    std::string cur_file;
    pyjson_value cases;
    for (size_t pos = 0; pos < tsv.size();) {
        const size_t nl = tsv.find('\n', pos);
        const std::string line = tsv.substr(pos, nl - pos);
        pos = nl + 1;
        if (line.empty() || line[0] == '#') continue;
        std::vector<std::string> f;
        for (size_t a = 0;;) {
            const size_t b = line.find('\t', a);
            f.push_back(line.substr(a, b - a));
            if (b == std::string::npos) break;
            a = b + 1;
        }
        if (f.size() != 10) { fail("R2: bad golden line"); continue; }
        if (f[0] != cur_file) {
            cases = load_json(cases_dir + "/" + f[0]);
            cur_file = f[0];
        }
        const bool cfg_b = f[1] == "B";
        std::vector<size_t> nodiv;   /* the cases whose ids the generator could not derive (a marker in the tools) */
        for (size_t a = 0; f[9] != "-" && a < f[9].size();) {
            const size_t b = f[9].find(',', a);
            nodiv.push_back((size_t)atol(f[9].substr(a, b - a).c_str()));
            if (b == std::string::npos) break;
            a = b + 1;
        }
        pulsar::Sha1 ht, hi;
        int ok = 0, ncmp = 0;
        long ntok = 0;
        std::map<std::string, int> refused;
        for (size_t idx = 0; idx < cases.a.size(); idx++) {
            const pyjson_value &c = cases.a[idx];
            conv cv;
            build_conv(*c.get("messages"), c.get("tools"), &cv);
            const nemotron_effort effort = cfg_b ? effort_of(efforts[idx % 3]) : nemotron_effort_default();
            nemotron_render_out out;
            std::string refusal;
            char line_buf[512];
            if (!render(cv, effort, cfg_b, &out, &refusal)) {
                refused[refusal]++;
                snprintf(line_buf, sizeof line_buf, "%zu refuse %s\n", idx, refusal.c_str());
                ht.update(line_buf, strlen(line_buf));
                continue;
            }
            ok++;
            const std::string l = std::to_string(idx) + " " + sha1_hex(out.text) + "\n";
            ht.update(l.data(), l.size());
            /* the ids, with the client spans guarding them: HF's whole-text encode where no client string spells a
             * marker, the guarded components where the messages do */
            if (std::find(nodiv.begin(), nodiv.end(), idx) != nodiv.end()) continue;
            const std::vector<int> ids = encode(t, out.text, &out.spans);
            ncmp++;
            ntok += (long)ids.size();
            const std::string li = std::to_string(idx) + " " + sha1_hex(ids_text(ids)) + "\n";
            if (const char *d = getenv("NEMOTRON_GATE_DUMP")) if (f[0] == d && !cfg_b) fprintf(stderr, "R2 %s", li.c_str());
            hi.update(li.data(), li.size());
        }
        uint8_t d1[20], d2[20];
        ht.final(d1);
        hi.final(d2);
        char h1[41], h2[41];
        for (int i = 0; i < 20; i++) {
            snprintf(h1 + 2 * i, 3, "%02x", d1[i]);
            snprintf(h2 + 2 * i, 3, "%02x", d2[i]);
        }
        std::string ref;
        for (const auto &kv : refused) ref += (ref.empty() ? "" : ",") + kv.first + "=" + std::to_string(kv.second);
        if (ref.empty()) ref = "-";
        lines++;
        cases_total += (int)cases.a.size();
        rendered_total += ok;
        compared_total += ncmp;
        tokens_total += ntok;
        for (const auto &kv : refused) refusals_total[kv.first] += kv.second;
        g_checks++;
        if (std::to_string(ok) != f[3] || ref != f[4] || h1 != f[5] || h2 != f[6] || std::to_string(ntok) != f[7] ||
            std::to_string(ncmp) != f[8]) {
            bad++;
            fail("R2 %s cfg %s: rendered %d/%s refusals %s/%s text %s ids %s tokens %ld/%s compared %d/%s", f[0].c_str(),
                 f[1].c_str(), ok, f[3].c_str(), ref.c_str(), f[4].c_str(), h1 == f[5] ? "=" : "DIFF",
                 h2 == f[6] ? "=" : "DIFF", ntok, f[7].c_str(), ncmp, f[8].c_str());
        }
    }
    std::string ref;
    for (const auto &kv : refusals_total) ref += " " + kv.first + "=" + std::to_string(kv.second);
    printf("R2 render corpus: %d file x config lines, %d cases, %d rendered (%d with ids graded, %ld tokens), "
           "refusals:%s; %d mismatched\n", lines, cases_total, rendered_total, compared_total, tokens_total, ref.c_str(),
           bad);
}

/* ---- the output parser --------------------------------------------------------------------------------------- */

struct parse_result {
    std::string reasoning, content, ev_reasoning, ev_content, calls, errors;
    std::vector<out_call> call_list;
};

static parse_result run_parser(const std::string &out, bool thinking, const char *tools, const std::vector<size_t> &cuts) {
    nemotron_output_parser p;
    char err[200];
    parse_result r;
    if (!p.init(thinking, tools, err, sizeof err)) { fail("parser init: %s", err); return r; }
    std::vector<out_event> ev;
    size_t at = 0;
    for (size_t cut : cuts) {
        p.feed(out.data() + at, cut - at, &ev);
        at = cut;
    }
    p.feed(out.data() + at, out.size() - at, &ev);
    p.finish(&ev);
    for (const auto &e : ev) {
        switch (e.kind) {
        case out_event::REASONING: r.ev_reasoning += e.text; break;
        case out_event::CONTENT: r.ev_content += e.text; break;
        case out_event::TOOL_END: r.calls += std::to_string(e.index) + ":" + e.name + ":" + e.arguments + "\n"; break;
        case out_event::ERROR: r.errors += e.text + "\n"; break;
        default: break;
        }
    }
    r.reasoning = p.reasoning();
    r.content = p.content();
    r.call_list = p.calls();
    CHECK(r.ev_reasoning == r.reasoning && r.ev_content == r.content, "parser: event deltas do not add up to the result");
    return r;
}

static bool contains(const char *s, const char *needle) { return s && strstr(s, needle); }

/* A turn whose text spells the grammar's own markers reads differently by construction (a reasoning that writes
 * "<tool_call>" opens a call there: vLLM skips to the next <function=, the kit refuses the block).  P1 and P2 skip
 * them (gen_nemotron_goldens.py ambiguous). */
static bool ambiguous(const nemotron_msg_in &m) {
    for (const char *k : {"<tool_call>", "</tool_call>", "<think>", "</think>"})
        if (contains(m.reasoning, k) || contains(m.content, k)) return true;
    for (int i = 0; i < m.n_calls; i++)
        if (contains(m.calls[i].arguments, "</parameter>") || contains(m.calls[i].arguments, "</function>") ||
            contains(m.calls[i].arguments, "</tool_call>") || contains(m.calls[i].name, ">"))
            return true;
    return false;
}

/* the sampled bytes of an assistant turn: the full render of [user, turn] past the generation prompt */
static bool sampled_turn(const conv &cv, const nemotron_msg_in &m, std::string *sampled, std::string *full) {
    conv one;
    nemotron_msg_in user = {};
    user.role = "user";
    user.content = "q";
    one.msgs = {user, m};
    one.tools = cv.tools;
    one.has_tools = cv.has_tools;
    nemotron_render_out out;
    std::string refusal;
    if (!render(one, NEMOTRON_EFFORT_HIGH, false, &out, &refusal)) return false;
    const std::string head = "<|im_start|>assistant\n<think>\n";
    const size_t a = out.text.rfind(head);
    if (a == std::string::npos) return false;
    *full = out.text;
    *sampled = out.text.substr(a + head.size(), out.text.size() - a - head.size() - strlen("<|im_end|>\n"));
    return true;
}

static void p1_roundtrip(const std::string &cases_dir, const std::string &dir) {
    std::string tsv;
    if (!read_file(dir + "/render_corpus.tsv", &tsv)) return;
    int turns = 0, n_ambiguous = 0, bad = 0, with_calls = 0, ws_reasoning = 0;
    unsigned rng = 12345;
    std::string last;
    for (size_t pos = 0; pos < tsv.size();) {
        const size_t nl = tsv.find('\n', pos);
        const std::string line = tsv.substr(pos, nl - pos);
        pos = nl + 1;
        if (line.empty() || line[0] == '#') continue;
        const std::string file = line.substr(0, line.find('\t'));
        if (file == last) continue;
        last = file;
        const pyjson_value cases = load_json(cases_dir + "/" + file);
        for (const auto &c : cases.a) {
            conv cv;
            build_conv(*c.get("messages"), c.get("tools"), &cv);
            if (cv.parts) continue;
            for (size_t i = 0; i < cv.msgs.size(); i++) {
                const nemotron_msg_in &m = cv.msgs[i];
                if (strcmp(m.role, "assistant") || !m.reasoning) continue;
                std::string r = m.reasoning;
                if (r.find_first_not_of(" \t\n\r") == std::string::npos) continue;   /* no reasoning: not sampled so */
                if (ambiguous(m)) { n_ambiguous++; continue; }
                std::string sampled, full;
                if (!sampled_turn(cv, m, &sampled, &full)) continue;   /* refused turns: R2 */
                /* a reasoning that ends in whitespace re-renders without it (vLLM's rstrip, the reading graded in P2):
                 * by construction not a round trip -- counted, not graded */
                if (isspace((unsigned char)r.back())) { ws_reasoning++; continue; }
                turns++;
                with_calls += m.n_calls > 0;
                const char *tools = cv.has_tools ? cv.tools.c_str() : NULL;
                const parse_result whole = run_parser(sampled, true, tools, {});
                std::vector<size_t> bytes;
                for (size_t k = 1; k < sampled.size(); k++) bytes.push_back(k);
                const parse_result each = run_parser(sampled, true, tools, bytes);
                std::vector<size_t> rnd;
                for (size_t k = 0; k < sampled.size();) {
                    rng = rng * 1103515245u + 12345u;
                    k += 1 + (rng >> 16) % 23;
                    if (k < sampled.size()) rnd.push_back(k);
                }
                const parse_result random = run_parser(sampled, true, tools, rnd);
                const int before = g_fail;
                g_checks++;
                if (!whole.errors.empty()) fail("P1 %s: parser error: %s", file.c_str(), whole.errors.c_str());
                if (each.reasoning != whole.reasoning || each.content != whole.content || each.calls != whole.calls ||
                    random.reasoning != whole.reasoning || random.content != whole.content || random.calls != whole.calls)
                    fail("P1 %s: chunking changed the parse", file.c_str());
                conv back;
                back.store.reserve(4 + 2 * whole.call_list.size());
                nemotron_msg_in a = {};
                a.role = "assistant";
                a.content = keep(&back, whole.content);
                a.reasoning = keep(&back, whole.reasoning);
                std::vector<nemotron_tool_call_in> calls;
                for (const auto &oc : whole.call_list) calls.push_back({keep(&back, oc.name), keep(&back, oc.arguments)});
                a.calls = calls.data();
                a.n_calls = (int)calls.size();
                std::string again_sampled, again_full;
                back.tools = cv.tools;
                back.has_tools = cv.has_tools;
                if (!sampled_turn(back, a, &again_sampled, &again_full)) {
                    fail("P1 %s: re-render refused", file.c_str());
                } else if (again_full != full) {
                    size_t d = 0;
                    while (d < again_full.size() && d < full.size() && again_full[d] == full[d]) d++;
                    std::string x, y;
                    pyjson_dump_string(again_full.data() + d, std::min<size_t>(60, again_full.size() - d), &x);
                    pyjson_dump_string(full.data() + d, std::min<size_t>(60, full.size() - d), &y);
                    fail("P1 %s: re-render differs at %zu: %s vs %s", file.c_str(), d, x.c_str(), y.c_str());
                }
                if (g_fail != before && ++bad > 20) { printf("P1: stopping after 20 failures\n"); return; }
            }
        }
    }
    printf("P1 output parser round trip: %d assistant turns (%d with tool calls; %d ambiguous by construction and %d "
           "whose reasoning ends in whitespace skipped), whole / byte-by-byte / random chunking; %d mismatched\n", turns,
           with_calls, n_ambiguous, ws_reasoning, bad);
}

/* One reading against vLLM's: true when equal up to the named departures (counted in *dep). */
struct departures {
    int content_strip = 0;   /* vLLM strips a turn's content when it holds calls; the kit keeps it (KEEP_UNLESS_BLANK) */
    int arg_typing = 0;      /* an argument value typed differently (vLLM: schema coercion; the kit: the template's
                              * own spelling -- see qwen_xml_call_body) */
    int after_calls = 0;     /* text after the calls: vLLM's final reading drops it (deferred content), the kit keeps it
                              * as content (the client sees what was sampled; Qwen's rule) */
};

static bool json_equal(const pyjson_value &a, const pyjson_value &b) {
    std::string x, y;
    pyjson_dump(a, &x);
    pyjson_dump(b, &y);
    return x == y;
}

static bool same_reading(const parse_result &r, const pyjson_value &want, departures *dep, std::string *why) {
    const std::string &wr = want.get("reasoning")->s, &wc = want.get("content")->s;
    const pyjson_value &wcalls = *want.get("calls");
    if (r.reasoning != wr) { *why = "reasoning [" + r.reasoning + "] vs [" + wr + "]"; return false; }
    if (r.call_list.size() != wcalls.a.size()) {
        *why = std::to_string(r.call_list.size()) + " calls vs " + std::to_string(wcalls.a.size());
        return false;
    }
    if (r.content != wc) {
        std::string s = r.content;
        const size_t lo = s.find_first_not_of(" \t\n\r"), hi = s.find_last_not_of(" \t\n\r");
        s = lo == std::string::npos ? "" : s.substr(lo, hi - lo + 1);
        if (r.call_list.empty() || s.compare(0, wc.size(), wc) != 0) {
            *why = "content [" + r.content + "] vs [" + wc + "]";
            return false;
        }
        if (s.size() > wc.size()) dep->after_calls++;
        else dep->content_strip++;
    }
    for (size_t i = 0; i < r.call_list.size(); i++) {
        const pyjson_value &w = wcalls.a[i];
        if (r.call_list[i].name != w.get("name")->s) { *why = "call name " + r.call_list[i].name; return false; }
        pyjson_value args;
        char jerr[100];
        if (!pyjson_parse(r.call_list[i].arguments.data(), r.call_list[i].arguments.size(), &args, jerr, sizeof jerr)) {
            *why = "arguments not JSON";
            return false;
        }
        const pyjson_value &wa = *w.get("arguments");
        if (args.o.size() != wa.o.size()) { *why = "argument count"; return false; }
        bool typed = false;
        for (size_t k = 0; k < args.o.size(); k++) {
            const pyjson_value *x = wa.get(args.o[k].first.c_str());
            if (!x) { *why = "argument key " + args.o[k].first; return false; }
            if (json_equal(args.o[k].second, *x)) continue;
            /* the same value, typed differently: one side a string the other's JSON spells, or a number spelt
             * another way (1.0 vs 1) */
            std::string ours, theirs;
            if (args.o[k].second.kind == pyjson_value::STR) ours = args.o[k].second.s; else pyjson_dump(args.o[k].second, &ours);
            if (x->kind == pyjson_value::STR) theirs = x->s; else pyjson_dump(*x, &theirs);
            const bool numbers = (args.o[k].second.kind == pyjson_value::INT || args.o[k].second.kind == pyjson_value::FLOAT) &&
                                 (x->kind == pyjson_value::INT || x->kind == pyjson_value::FLOAT) &&
                                 strtod(ours.c_str(), NULL) == strtod(theirs.c_str(), NULL);
            if (ours != theirs && !numbers) { *why = "argument " + args.o[k].first + ": " + ours + " vs " + theirs; return false; }
            typed = true;
        }
        dep->arg_typing += typed;
    }
    return true;
}

/* gen_nemotron_goldens.py canon_value: an argument value as text (a string itself, anything else its JSON), a
 * boolean's lower-case, a null's "null", a number's text as repr(float) -- what both readings agree on when they
 * type a value differently */
static pyjson_value canon_value(const pyjson_value &v) {
    pyjson_value out;
    out.kind = pyjson_value::STR;
    if (v.kind == pyjson_value::STR) out.s = v.s;
    else pyjson_dump(v, &out.s);
    if (out.s == "True" || out.s == "False" || out.s == "true" || out.s == "false") {
        out.s = out.s[0] == 'T' || out.s[0] == 't' ? "true" : "false";
        return out;
    }
    if (out.s == "None" || out.s == "null") {
        out.s = "null";
        return out;
    }
    pyjson_value x;
    char jerr[8];
    if (!pyjson_parse(out.s.data(), out.s.size(), &x, jerr, sizeof jerr)) return out;
    if (x.kind != pyjson_value::INT && x.kind != pyjson_value::FLOAT) return out;
    const double f = x.kind == pyjson_value::INT ? strtod(x.num.c_str(), NULL) : x.f;
    if (!(f == f) || f == HUGE_VAL || f == -HUGE_VAL) return out;
    pyjson_value fv;
    fv.kind = pyjson_value::FLOAT;
    fv.f = f;
    out.s.clear();
    pyjson_dump(fv, &out.s);
    return out;
}

/* gen_nemotron_goldens.py canon_line over the kit's reading */
static std::string canon_line(const parse_result &r) {
    pyjson_value line;
    line.kind = pyjson_value::ARR;
    pyjson_value s;
    s.kind = pyjson_value::STR;
    s.s = r.reasoning;
    line.a.push_back(s);
    s.s = r.content;
    if (!r.call_list.empty()) {
        const size_t lo = s.s.find_first_not_of(" \t\n\r\f\v"), hi = s.s.find_last_not_of(" \t\n\r\f\v");
        s.s = lo == std::string::npos ? "" : s.s.substr(lo, hi - lo + 1);
    }
    line.a.push_back(s);
    pyjson_value calls;
    calls.kind = pyjson_value::ARR;
    for (const auto &c : r.call_list) {
        pyjson_value pair;
        pair.kind = pyjson_value::ARR;
        pyjson_value name;
        name.kind = pyjson_value::STR;
        name.s = c.name;
        pair.a.push_back(name);
        pyjson_value args, canon;
        char jerr[8];
        canon.kind = pyjson_value::OBJ;
        if (pyjson_parse(c.arguments.data(), c.arguments.size(), &args, jerr, sizeof jerr))
            for (const auto &kv : args.o) canon.o.push_back({kv.first, canon_value(kv.second)});
        pair.a.push_back(canon);
        calls.a.push_back(pair);
    }
    line.a.push_back(calls);
    std::string out;
    pyjson_dump(line, &out);
    return out + "\n";
}

static void p2_vllm(const std::string &dir, const std::string &cases_dir) {
    const pyjson_value units = load_json(dir + "/parse_cases.json");
    const pyjson_value hand = load_json(dir + "/render_cases.json");
    std::string tools_json;
    for (const auto &h : hand.a)
        if (h.get("name")->s == "tool_round") tools_json = h.get("tools")->s;
    departures dep;
    int bad = 0;
    for (size_t u = 0; u < units.a.size(); u++) {
        const pyjson_value &c = units.a[u];
        const std::string text = c.get("text")->s;
        std::vector<size_t> bytes;
        for (size_t k = 1; k < text.size(); k++) bytes.push_back(k);
        const parse_result whole = run_parser(text, c.get("thinking")->b, tools_json.c_str(), {});
        const parse_result each = run_parser(text, c.get("thinking")->b, tools_json.c_str(), bytes);
        std::string why;
        g_checks++;
        if (!same_reading(whole, *c.get("expect"), &dep, &why) || each.calls != whole.calls ||
            each.reasoning != whole.reasoning || each.content != whole.content) {
            bad++;
            fail("P2 unit %zu: %s", u, why.empty() ? "chunking changed the reading" : why.c_str());
        }
    }
    /* the corpus: every assistant turn with reasoning, as sampled, read by both */
    std::string tsv;
    int turns = 0, files_bad = 0;
    if (!cases_dir.empty() && read_file(dir + "/parse_corpus.tsv", &tsv)) {
        for (size_t pos = 0; pos < tsv.size();) {
            const size_t nl = tsv.find('\n', pos);
            const std::string line = tsv.substr(pos, nl - pos);
            pos = nl + 1;
            if (line.empty() || line[0] == '#') continue;
            const std::string file = line.substr(0, line.find('\t'));
            const pyjson_value cases = load_json(cases_dir + "/" + file);
            int n = 0;
            pulsar::Sha1 h;
            for (const auto &c : cases.a) {
                conv cv;
                build_conv(*c.get("messages"), c.get("tools"), &cv);
                for (size_t i = 0; i < cv.msgs.size(); i++) {
                    const nemotron_msg_in &m = cv.msgs[i];
                    if (strcmp(m.role, "assistant") || !m.reasoning) continue;
                    const std::string r = m.reasoning;
                    if (r.find_first_not_of(" \t\n\r\f\v") == std::string::npos || ambiguous(m)) continue;
                    std::string sampled, full;
                    if (cv.parts || !sampled_turn(cv, m, &sampled, &full)) continue;
                    n++;
                    const std::string l = canon_line(run_parser(sampled, true, cv.has_tools ? cv.tools.c_str() : NULL, {}));
                    h.update(l.data(), l.size());
                    if (const char *d = getenv("NEMOTRON_GATE_DUMP")) if (file == d) fprintf(stderr, "%s", l.c_str());
                }
            }
            turns += n;
            uint8_t d[20];
            h.final(d);
            char hx[41];
            for (int i = 0; i < 20; i++) snprintf(hx + 2 * i, 3, "%02x", d[i]);
            const size_t t1 = line.find('\t'), t2 = line.find('\t', t1 + 1);
            g_checks++;
            if (std::to_string(n) != line.substr(t1 + 1, t2 - t1 - 1) || line.substr(t2 + 1) != hx) {
                files_bad++;
                fail("P2 %s: %d turns vs the golden's %s, canonical readings %s", file.c_str(), n,
                     line.substr(t1 + 1, t2 - t1 - 1).c_str(), line.substr(t2 + 1) == hx ? "=" : "DIFF");
            }
        }
    }
    printf("P2 parser vs vLLM nemotron_v3: %zu units (x 2 chunkings), %d mismatched; departures: content stripped by "
           "vLLM beside calls %d, text after calls %d, argument typing %d; corpus: %d turns, %d files whose canonical "
           "readings differ\n", units.a.size(), bad, dep.content_strip, dep.after_calls, dep.arg_typing, turns, files_bad);
}

static void e1_effort(void) {
    int bad = 0;
    const int before = g_fail;
    CHECK(nemotron_effort_default() == NEMOTRON_EFFORT_HIGH, "E1: the default is not the template's own (high)");
    for (const char *n : {"none", "medium", "high"}) {
        nemotron_effort e;
        CHECK(nemotron_effort_parse(n, &e) && !strcmp(nemotron_effort_name(e), n), "E1: %s does not round trip", n);
    }
    for (const char *n : {"low", "xhigh", "max", "", "HIGH", "minimal"}) {
        nemotron_effort e;
        CHECK(!nemotron_effort_parse(n, &e), "E1: %s parsed", n);
    }
    CHECK(!strcmp(nemotron_generation_prompt(NEMOTRON_EFFORT_NONE), "<|im_start|>assistant\n<think></think>") &&
              !strcmp(nemotron_generation_prompt(NEMOTRON_EFFORT_MEDIUM), "<|im_start|>assistant\n<think>\n"),
          "E1: generation prompts");
    bad += g_fail != before;
    printf("E1 effort map: none / medium / high (default), %d mismatched\n", bad);
}

/* A conversation built turn by turn -- the head, each turn, each sampled assistant turn followed by its close -- is
 * the full render byte for byte where the template composes: a tool loop after the last user message (a later user
 * message truncates the history's reasoning, by the template's design).  Every piece the front end renders tokenizes
 * on its own to the full render's ids over its bytes. */
static void c1_composition(const bpe_tokenizer *t) {
    struct piece { std::string text; std::vector<pulsar_text_span> spans; bool sampled; };
    const nemotron_tool_call_in call = {"read_file", "{\"path\": \"a.txt\", \"lines\": 3}"};
    const nemotron_tool_call_in call2 = {"grep", "{\"pattern\": \"x\"}"};
    const nemotron_msg_in m[] = {
        {"system", "You are terse.", NULL, NULL, 0, NULL},
        {"user", "Read a.txt then grep it.", NULL, NULL, 0, NULL},
        {"assistant", "Reading it.", "Use the tool.", &call, 1, NULL},
        {"tool", "line one\nline two.", NULL, NULL, 0, NULL},
        {"assistant", "", "Now grep.", &call2, 1, NULL},
        {"tool", "match", NULL, NULL, 0, NULL},
        {"tool", "second result", NULL, NULL, 0, NULL},
        {"assistant", "Done: one match.", "Summarize.", NULL, 0, NULL},
    };
    const int len = (int)(sizeof m / sizeof m[0]);
    int bad = 0, n = 0;
    for (nemotron_effort eff : {NEMOTRON_EFFORT_HIGH, NEMOTRON_EFFORT_MEDIUM, NEMOTRON_EFFORT_NONE}) {
        const bool thinking = eff != NEMOTRON_EFFORT_NONE;
        char err[300] = "";
        std::vector<piece> pieces;
        nemotron_render_out r;
        bool ok = nemotron_chat_render_head(m[0].content, &r, err, sizeof err);
        pieces.push_back({r.text, r.spans, false});
        int i = 1;
        bool first = true;
        while (ok && i < len) {
            int j = i;
            while (j < len && strcmp(m[j].role, "assistant")) j++;
            if (first) ok = nemotron_chat_render_turn(m + i, j - i, eff, true, &r, err, sizeof err);
            else ok = nemotron_chat_render_tail(m + i, j - i, eff, &r, err, sizeof err);
            pieces.push_back({r.text, r.spans, false});
            first = false;
            if (!ok || j == len) break;
            nemotron_msg_in a = m[j];
            if (!thinking) a.reasoning = NULL;
            ok = nemotron_chat_render_assistant_turn(a, thinking, &r, err, sizeof err);
            pieces.push_back({r.text, r.spans, true});
            i = j + 1;
        }
        std::vector<nemotron_msg_in> full_msgs(m, m + len);
        if (!thinking)
            for (auto &x : full_msgs) x.reasoning = NULL;
        nemotron_render_out full;
        ok = ok && nemotron_chat_render({full_msgs.data(), len, NULL, eff, false}, &full, err, sizeof err);
        std::string text;
        for (const piece &p : pieces) text += p.text;
        const int before = g_fail;
        CHECK(ok, "C1 effort %s: refused: %s", nemotron_effort_name(eff), err);
        CHECK(!ok || text == full.text, "C1 effort %s: the turns' text is not the full render", nemotron_effort_name(eff));
        if (ok && text == full.text) {
            const std::vector<int> want = encode(t, full.text, &full.spans);
            std::vector<size_t> at(want.size() + 1, 0);
            for (size_t k = 0; k < want.size(); k++) {
                size_t nb = 0;
                bpe_tokenizer_token_bytes(t, want[k], &nb);
                at[k + 1] = at[k] + nb;
            }
            size_t lo = 0;
            for (size_t q = 0; q < pieces.size(); q++) {
                const piece &p = pieces[q];
                const size_t hi = lo + p.text.size();
                if (!p.sampled && !p.text.empty()) {
                    const bool open_end = q + 1 < pieces.size() && pieces[q + 1].sampled;
                    std::vector<int> got = encode(t, p.text, &p.spans);
                    if (open_end) got.pop_back();
                    size_t got_hi = lo;
                    for (int id : got) {
                        size_t nb = 0;
                        bpe_tokenizer_token_bytes(t, id, &nb);
                        got_hi += nb;
                    }
                    const auto a = std::find(at.begin(), at.end(), lo);
                    const auto b = std::find(at.begin(), at.end(), got_hi);
                    const bool edges = a != at.end() && b != at.end();
                    const std::vector<int> whole = edges ? std::vector<int>(want.begin() + (a - at.begin()),
                                                                            want.begin() + (b - at.begin()))
                                                         : std::vector<int>();
                    CHECK(edges && got == whole, "C1 effort %s piece %zu [%zu, %zu): %s", nemotron_effort_name(eff), q, lo,
                          hi, edges ? first_diff(got, whole).c_str() : "its edges are not token edges of the whole");
                }
                lo = hi;
            }
        }
        bad += g_fail != before;
        n++;
    }
    printf("C1 turn-by-turn composition (a tool loop): %d efforts, %d mismatched\n", n, bad);
}

int main(int argc, char **argv) {
    std::string tok_dir, vec_dir, cases_dir, calib;
    for (int i = 1; i < argc; i++) {
        const std::string a = argv[i];
        if (a == "--tok" && i + 1 < argc) tok_dir = argv[++i];
        else if (a == "--vectors" && i + 1 < argc) vec_dir = argv[++i];
        else if (a == "--cases" && i + 1 < argc) cases_dir = argv[++i];
        else if (a == "--calib" && i + 1 < argc) calib = argv[++i];
        else {
            fprintf(stderr, "usage: nemotron_chat_gate --tok DIR --vectors DIR [--cases DIR] [--calib FILE]\n");
            return 2;
        }
    }
    if (tok_dir.empty() || vec_dir.empty()) {
        fprintf(stderr, "usage: nemotron_chat_gate --tok DIR --vectors DIR [--cases DIR] [--calib FILE]\n");
        return 2;
    }
    std::string tj, gj;
    if (!read_file(tok_dir + "/tokenizer.json", &tj) || !read_file(tok_dir + "/generation_config.json", &gj)) {
        fprintf(stderr, "nemotron_chat_gate: %s must hold tokenizer.json and generation_config.json\n", tok_dir.c_str());
        return 2;
    }
    char err[512];
    bpe_tokenizer *t = bpe_tokenizer_load_hf(tj.data(), tj.size(), gj.data(), gj.size(), err, sizeof err);
    if (!t) {
        fprintf(stderr, "nemotron_chat_gate: %s\n", err);
        return 1;
    }
    const pyjson_value meta = load_json(vec_dir + "/meta.json");
    printf("nemotron_chat_gate: tokenizer %s (%d ids, pattern %s), goldens from transformers %s / tokenizers %s / vLLM %.10s\n",
           tok_dir.c_str(), bpe_tokenizer_n_tokens(t), bpe_tokenizer_pattern(t)->name,
           meta.get("transformers")->s.c_str(), meta.get("tokenizers")->s.c_str(), meta.get("vllm")->s.c_str());
    CHECK(!strcmp(bpe_tokenizer_pattern(t)->name, "tekken"), "the pre-tokenizer is not tekken");
    CHECK(bpe_tokenizer_n_tokens(t) == atoi(meta.get("n_tokens")->num.c_str()), "token count %d vs HF %s",
          bpe_tokenizer_n_tokens(t), meta.get("n_tokens")->num.c_str());
    CHECK(json_ids(*meta.get("stop_ids")) == bpe_tokenizer_stop_ids(t), "stop ids differ from generation_config");
    t1_adversarial(t, vec_dir);
    t2_spans(t, vec_dir);
    t3_sweep(t, vec_dir, sweep_context);
    if (!calib.empty()) t4_calib(t, vec_dir, calib);
    else printf("T4 calibration corpus: SKIPPED (no --calib)\n");
    r1_hand(t, vec_dir);
    if (!cases_dir.empty()) {
        r2_corpus(t, vec_dir, cases_dir);
        p1_roundtrip(cases_dir, vec_dir);
    } else {
        printf("R2 render corpus / P1 parser round trip: SKIPPED (no --cases)\n");
    }
    p2_vllm(vec_dir, cases_dir);
    e1_effort();
    c1_composition(t);
    bpe_tokenizer_free(t);
    printf("\nnemotron_chat_gate: %d checks, %d failed -- %s\n", g_checks, g_fail, g_fail ? "FAIL" : "PASS");
    return g_fail ? 1 : 0;
}
